using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct ClaimId : IEquatable<ClaimId>, IComparable<ClaimId>
    {
        public Guid Value { get; }

        public ClaimId(Guid value)
        {
            Value = value;
        }

        public static ClaimId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static ClaimId NewRandom() => new ClaimId(Guid.NewGuid());

        public static ClaimId Parse(string text) => new ClaimId(Guid.Parse(text));

        public static bool TryParse(string text, out ClaimId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new ClaimId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(ClaimId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is ClaimId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(ClaimId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(ClaimId left, ClaimId right) => left.Equals(right);

        public static bool operator !=(ClaimId left, ClaimId right) => !left.Equals(right);
    }
}
